update public.households set state = state || '{"recipes":[{"id":"rice","title":"Rice","description":"Keep this recipe","servings":2,"prepMinutes":0,"cookMinutes":10,"category":"Sides","tags":[],"favorite":false,"wantToTry":true,"image":"","sourceUrl":"","author":"","ingredients":[{"id":"line","name":"rice","amount":200,"unit":"g","group":"","note":"","raw":"200 g rice"}],"steps":["Cook."],"notes":"Original notes","createdAt":"2026-11-01T00:00:00.000Z","updatedAt":"2026-11-01T00:00:00.000Z"}],"pantry":[{"id":"stock","name":"rice","amount":100,"unit":"g","location":"Pantry","note":""}],"shopping":[{"id":"grocery","key":"rice","name":"rice","amount":200,"unit":"g","note":"","group":"Ingredients","checked":false,"manual":true,"override":false,"needed":null,"uncertain":false,"addedToPantry":false}]}'::jsonb, revision = 7 where name = 'Our kitchen';
update public.households set state = jsonb_set(state,'{recipes}',(select state->'recipes' from public.households where name = 'Our kitchen')) where name = 'Other kitchen';
